            before = week_used.get(week, 0)
            counted = row["paid"] - row["daily_ot"]
            after = before + counted
            week_used[week] = after
            row["weekly_ot"] = max(0, after - max(before, 2400))
        total_pay = Fraction(0)
        overtime = 0
        for row in rows:
            ot = row["daily_ot"] + row["weekly_ot"]
            regular = row["paid"] - ot
            overtime += ot
            rate = None
            for effective, value in rates.get(emp, []):
                if effective <= row["day"]:
                    rate = value
            if rate is None:
                rate = rates[emp][0][1] if rates.get(emp) else Decimal(0)
            rate = Fraction(rate)
            total_pay += rate * (regular + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * row["night"] / 60
        cents = int((total_pay * 100 + Fraction(1, 2)) // 1)
        result[emp] = {
            "shifts": len(rows),
            "paid_minutes": sum(row["paid"] for row in rows),
            "overtime_minutes": overtime,
            "night_minutes": sum(row["night"] for row in rows),
            "gross": "%d.%02d" % divmod(cents, 100),
            "_cents": cents,
        }

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    cents_total = 0
    for value in result.values():
        for field in totals:
            totals[field] += value[field]
        cents_total += value.pop("_cents")
    totals["gross"] = "%d.%02d" % divmod(cents_total, 100)
