def round_instant(ts, zone):
    offset = int(datetime.fromtimestamp(ts, tz=zone).utcoffset().total_seconds())
    return ((ts + offset + 180) // 360) * 360 - offset


def note_open(exceptions, pending, home_zone, start, end):
    if start <= datetime.fromtimestamp(pending[0], tz=home_zone).date() <= end:
        exceptions["open_shifts"] += 1


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
