                total += 1
        return total

    for emp, home_site in employees.items():
        home_zone = sites[home_site][0]
        items = sorted(by_emp.get(emp, []))
        kept = []
        for item in items:
            site = item[2]
            if kept and kept[-1][4] == item[4] and item[0] - kept[-1][0] <= 300:
                zone = sites[site][0]
                if start <= workday(round_instant(item[0], zone), home_zone) <= end:
                    exceptions["duplicates_dropped"] += 1
                continue
            kept.append(item)
        rounded = []
        for ts, _, site, pid, direction in kept:
            zone = sites[site][0]
            rounded.append((round_instant(ts, zone), direction, site))
        shifts = []
        index = 0
        pending = None
        for rts, direction, site in rounded:
            if direction == "IN":
                if pending is not None:
                    note_open(exceptions, pending, home_zone, start, end)
                pending = (rts, site)
            else:
                if pending is not None and rts - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], rts, pending[1]))
                    pending = None
                else:
                    if pending is not None:
                        note_open(exceptions, pending, home_zone, start, end)
                        pending = None
                    if start <= workday(rts, home_zone) <= end:
                        exceptions["orphan_outs"] += 1
        if pending is not None:
            note_open(exceptions, pending, home_zone, start, end)

        rows = []
        for begin, finish, site in shifts:
            day = workday(begin, home_zone)
            if not start <= day <= end:
                continue
            worked = max(0, (finish - begin) // 60)
            paid = worked - 30 if worked > 360 else worked
            zone_name = str(sites[site][0])
            night = min(night_minutes(zone_name, sites[site][0], begin, finish), paid)
            rows.append({"begin": begin, "day": day, "paid": paid, "night": night})
        rows.sort(key=lambda row: row["begin"])
        daily_used = {}
        for row in rows:
            before = daily_used.get(row["day"], 0)
            after = before + row["paid"]
            daily_used[row["day"]] = after
            row["daily_ot"] = max(0, after - max(before, 480))
        week_used = {}
        for row in rows:
            week = row["day"] - timedelta(days=row["day"].weekday())
            before = week_used.get(week, 0)
            counted = row["paid"] - row["daily_ot"]
            after = before + counted
            week_used[week] = after
            row["weekly_ot"] = max(0, after - max(before, 2400))
        total_pay = Fraction(0)
        overtime = 0
        for row in rows:
            ot = row["daily_ot"] + row["weekly_ot"]
            regular = row["paid"] - ot
            overtime += ot
            rate = None
            for effective, value in rates.get(emp, []):
                if effective <= row["day"]:
                    rate = value
            if rate is None:
                rate = rates[emp][0][1] if rates.get(emp) else Decimal(0)
            rate = Fraction(rate)
            total_pay += rate * (regular + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * row["night"] / 60
        cents = int((total_pay * 100 + Fraction(1, 2)) // 1)
        result[emp] = {
            "shifts": len(rows),
            "paid_minutes": sum(row["paid"] for row in rows),
            "overtime_minutes": overtime,
            "night_minutes": sum(row["night"] for row in rows),
            "gross": "%d.%02d" % divmod(cents, 100),
            "_cents": cents,
        }

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    cents_total = 0
    for value in result.values():
        for field in totals:
            totals[field] += value[field]
        cents_total += value.pop("_cents")
    totals["gross"] = "%d.%02d" % divmod(cents_total, 100)
    summary = {"period": {"start": period["start"], "end": period["end"]}, "employees": result,
               "exceptions": exceptions, "totals": totals}
    Path(output_file).write_text(json.dumps(summary, indent=2))


def round_instant(ts, zone):
    offset = int(datetime.fromtimestamp(ts, tz=zone).utcoffset().total_seconds())
    return ((ts + offset + 180) // 360) * 360 - offset


def note_open(exceptions, pending, home_zone, start, end):
    if start <= datetime.fromtimestamp(pending[0], tz=home_zone).date() <= end:
        exceptions["open_shifts"] += 1


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
